MAP
    NAME "SS_MAP_RURAL_POZOS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB 
    SYMBOL
    NAME "manantial"
    TYPE pixmap
    IMAGE "includes/symbols/Manantial.png"
    END #SYMBOL
   
   CONFIG "MS_ERRORFILE" "/srv/mapserver/err_pozos_rural.txt"
   DEBUG 0
    LAYER
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        NAME "SS_MAP_RURAL_POZOS"
        STATUS DEFAULT
        METADATA
            'ows_title' 'pozos_rural'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
        END #METADATA
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
		DATA "gm_pozo_rural from public.l_pozo_rural using unique id_elemento_geografico using srid=32614"
        TYPE POINT
        LABELITEM "nb_pozo_rural"
        #LABELCACHE ON
        CLASS
            NAME "Pozo"
            EXPRESSION ([cl_tipo]= 2)
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                POSITION UC
               # OFFSET 0 35
                SIZE 12
                COLOR 0 117 63
                OUTLINECOLOR 255 255 255
            END #LABEL
            STYLE
                #SYMBOL "pozorural"
                SYMBOL "square"
                SIZE 20
                COLOR 35 110 3
                WIDTH 1
                OUTLINECOLOR 0 0 0
            END #STYLE
        END #CLASS   
        CLASS
            NAME "Manantial"
            EXPRESSION ([cl_tipo]= 1)
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                POSITION UC
               # OFFSET 0 35
                SIZE 12
                COLOR 0 0 0
                OUTLINECOLOR 255 255 255
            END #LABEL
            STYLE
                SYMBOL "manantial"
                SIZE 25
            END #STYLE
        END 
    END #LAYER#
END #MAP#

   